// Transform incoming data to Supabase format
const input = items[0].json;

// Map field names from camelCase to snake_case for Supabase
const transformed = {
  order_id: input.autoGeneratedOrderId,
  unique_order_record_id: input.uniqueOrderRecordId,
  device_type: input.itemName || input.deviceType,
  date_ordered: new Date(input.dateOrdered).toISOString().split('T')[0],
  quantity_ordered: input._originalCartItem?.quantity || input.quantityOrdered || 1,
  qty_dispatched: 0,
  item_category: input.itemCategory,
  item_description: input.itemDescription,
  item_nature: input.itemNature,
  contractor_company: input.contractorCompany,
  region: input.region,
  technician: input._originalFormData?.technician || input.technician,
  ordered_by: input._originalFormData?.orderedBy || input.orderedBy,
  order_location: input._originalFormData?.orderLocation || input.orderLocation,
  tech_email: input._originalFormData?.onBehalfOf || input.onBehalfOf,
  pick_status: 'Pending',
  dispatch_status: 'Pending'
};

return [{ json: transformed }];
